    "site.admin.staff.roleNote.him": "सूचना-जारी करने के अनुरोधों का निर्णय और रिकॉर्ड करने के लिए चार्ट पढ़ना।",
    "site.admin.staff.roleNote.bloodBank": "केवल क्रॉसमैच, जारी करना और ट्रांसफ्यूजन प्रशासित करना।",
