    "site.admin.hospital.noteWriters.title": "क्लिनिकल नोट कौन लिख सकता है",
    "site.admin.hospital.noteWriters.intro": "डॉक्टर और एडमिन हमेशा नोट लिख सकते हैं। मरीज की टाइमलाइन पर डॉक्यूमेंट करने के लिए अपने अस्पताल द्वारा भरोसेमंद किसी भी अन्य भूमिका पर टिक करें। यह उन्हें केवल नोट लिखने की अनुमति देता है और कुछ नहीं: यह उन्हें दवा लिखने, ऑर्डर करने या कुछ भी बदलने की अनुमति नहीं देता है।",
