    "site.admin.save": "सहेजें",
    "site.admin.hospital.noteWriters.savedNone": "सहेजा गया। केवल प्रिस्क्राइबर ही नोट लिख सकते हैं।",
    "site.admin.hospital.noteWriters.savedOne": "सहेजा गया। {n} अतिरिक्त भूमिका नोट लिख सकती है।",
    "site.admin.hospital.noteWriters.savedMany": "सहेजा गया। {n} अतिरिक्त भूमिकाएं नोट लिख सकती हैं।",
    "site.admin.hospital.printLang.title": "मरीज की भाषा में प्रिंटआउट",
    "site.admin.hospital.printLang.toggle": "मरीज के प्रिस्क्रिप्शन और डिस्चार्ज समरी प्रिंट पर दूसरी भाषा का विकल्प दें",
    "site.admin.hospital.printLang.intro": "अंग्रेजी प्रिंट हमेशा पूरा होता है और आधिकारिक होता है। दूसरी भाषा इसके बगल में मुद्रित की जाती है, जिसे अनुवाद के रूप में चिह्नित किया जाता है, और इसमें केवल हेडिंग, लेबल और मरीज के निर्देश शामिल होते हैं जिन्हें प्रिस्क्राइबर ने तय सूची से चुना है। दवाओं के नाम, खुराक, फ्रीक्वेंसी, निदान, परिणाम और टाइप की गई कोई भी चीज़ केवल अंग्रेजी में प्रिंट की जाती है। जो अनुवाद अभी नहीं लिखे गए हैं वे अंग्रेजी में दिखाई देते हैं।",
    "site.admin.hospital.printLang.savedOn": "सहेजा गया। प्रिंट में दूसरी भाषा का विकल्प है।",
