    "site.admin.hospital.token.intro": "प्रिफिक्स का उपयोग केवल तभी किया जाता है जब प्रत्येक विभाग अलग-अलग नंबर देता है, और फिर हर विभाग को अपने स्वयं के प्रिफिक्स की आवश्यकता होती है: डेस्क बिना प्रिफिक्स वाले विभाग में टोकन नहीं दे सकता है। एक खाली प्रिफिक्स उस विभाग कोड का उपयोग करता है जो ग्रे दिखाया गया है जब वह कोड एक से तीन अक्षर या अंक का हो। नंबर हर दिन 1 से फिर से शुरू होते हैं, और पहले से दिया गया टोकन कभी नहीं बदलता है, जिसमें मरीज को किसी अन्य विभाग के कमरे में स्थानांतरित करना भी शामिल है।",
