    "site.admin.webhooks.intro1": "एक webhook दूसरे सिस्टम को बताता है कि यहां कुछ हुआ है। इसमें केवल इवेंट प्रकार और एक अपारदर्शी id होती है: कभी भी कोई नाम, नंबर, टेस्ट या वैल्यू नहीं।",
    "site.admin.webhooks.intro2": "प्राप्तकर्ता सिस्टम अपने स्वयं के SMART एक्सेस के साथ WardSynQ FHIR API के माध्यम से विवरण पढ़ता है, जहां इस अस्पताल की अनुमतियां और ऑडिट ट्रेल लागू होते हैं।",
